+    }
+
+    /** 결과 상한에 걸려 구간을 다 받지 못한 응답. */
+    public static NewsFetchResult capped(List<CollectedNewsItem> items) {
+        return new NewsFetchResult(Objects.requireNonNull(items), false, true, null, null);
