+                sourceKey,
+                NewsCollectionStatus.INCOMPLETE,
+                cursor,
+                now,
+                lastSuccessAt,
+                nextAttemptAt,
+                retryCount,
+                RESULT_CAP_REACHED,
+                null,
+                null);
+    }
