+            String publisherKey,
+            String displayName,
+            String language,
+            String registeredDomain,
+            String rssUrl,
+            PermissionStatus permissionStatus,
+            Instant permissionUpdatedAt,
+            boolean enabled,
+            String etag,
+            String lastModified) {
+        return new NewsPublisher(
+                Objects.requireNonNull(id, "id must not be null"),
+                publisherKey,
+                displayName,
+                language,
+                registeredDomain,
+                rssUrl,
+                permissionStatus,
+                permissionUpdatedAt,
+                enabled,
+                etag,
+                lastModified);
