+                id,
+                publisherKey,
+                displayName,
+                language,
+                registeredDomain,
+                rssUrl,
+                permissionStatus,
+                permissionUpdatedAt,
+                false,
+                etag,
+                lastModified);
+    }
+
+    /** 공개 환경에 노출할 수 있는 매체인지 여부(spec FR-016). */
