+        if (entity.getId() != null) {
+            entity.refreshMembership(
+                    digest.getRepresentative().getId(),
+                    digest.getRepresentativeTitle(),
+                    digest.getFactualSummary(),
+                    digest.firstPublishedAt(),
+                    digest.latestPublishedAt(),
